const query = $input.first().json.query || '';
const countryInput = ($input.first().json.country || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// Location bias centers and defaults by country/city
const biasMap = {
  peru_lima:    { bias: 'circle:30000@-12.06,-77.04', country: 'Peru', city: 'Lima' },
  peru_piura:   { bias: 'circle:15000@-5.19,-80.63',  country: 'Peru', city: 'Piura' },
  colombia:     { bias: 'circle:30000@4.65,-74.05',    country: 'Colombia', city: 'Bogota' },
  mexico_cdmx:  { bias: 'circle:30000@19.43,-99.13',   country: 'Mexico', city: 'Ciudad de Mexico' },
  mexico_gdl:   { bias: 'circle:30000@20.67,-103.35',  country: 'Mexico', city: 'Guadalajara' },
  mexico_mty:   { bias: 'circle:30000@25.67,-100.31',  country: 'Mexico', city: 'Monterrey' },
};

// Peru district keywords
const peruKw = [
  'lima','callao','miraflores','surco','santiago de surco','san isidro',
  'san miguel','san borja','la molina','barranco','chorrillos','jesus maria',
  'lince','magdalena','pueblo libre','brena','rimac','san martin de porres',
  'los olivos','comas','independencia','carabayllo','ate','santa anita',
  'el agustino','la victoria','san juan de lurigancho','sjl',
  'villa el salvador','villa maria del triunfo','san juan de miraflores',
  'lurin','pachacamac','cieneguilla','chaclacayo','chosica','puente piedra',
  'ancon','bellavista','la perla','ventanilla','mi peru','la punta',
  'cercado de lima','san luis','surquillo','breña','miramar'
];
const colombiaKw = [
  'bogota','colombia','chapinero','usaquen','suba','engativa','fontibon',
  'kennedy','teusaquillo','candelaria','santa fe','bosa','tunjuelito',
  'ciudad bolivar','rafael uribe','antonio narino','puente aranda',
  'barrios unidos','martires'
];
const mexicoGdlKw = ['guadalajara','zapopan','tlaquepaque','tonala'];
const mexicoMtyKw = ['monterrey','san pedro garza','san nicolas','apodaca','escobedo'];
const mexicoKw = [
  'cdmx','ciudad de mexico','polanco','condesa','roma norte','coyoacan',
  'benito juarez','miguel hidalgo','azcapotzalco','alvaro obregon',
  'cuauhtemoc','iztapalapa','iztacalco','gustavo a. madero','xochimilco',
  'tlahuac','milpa alta','cuajimalpa','magdalena contreras','huixquilucan',
  'ecatepec','naucalpan','tlalnepantla','mexico'
];

let detected = null;
const q = query.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// 1. Explicit country parameter
if (countryInput) {
  if (countryInput.includes('peru') || countryInput === 'pe') {
    detected = q.includes('piura') ? biasMap.peru_piura : biasMap.peru_lima;
  } else if (countryInput.includes('colombia') || countryInput === 'co') {
    detected = biasMap.colombia;
  } else if (countryInput.includes('mexico') || countryInput === 'mx') {
    if (mexicoGdlKw.some(k => q.includes(k))) detected = biasMap.mexico_gdl;
    else if (mexicoMtyKw.some(k => q.includes(k))) detected = biasMap.mexico_mty;
    else detected = biasMap.mexico_cdmx;
  }
}

// 2. Detect from query keywords
if (!detected) {
  const peruSpecific = peruKw.filter(k => !['peru'].includes(k));
  if (peruSpecific.some(k => q.includes(k))) {
    detected = q.includes('piura') ? biasMap.peru_piura : biasMap.peru_lima;
  } else if (colombiaKw.some(k => q.includes(k))) {
    detected = biasMap.colombia;
  } else if (mexicoGdlKw.some(k => q.includes(k))) {
    detected = biasMap.mexico_gdl;
  } else if (mexicoMtyKw.some(k => q.includes(k))) {
    detected = biasMap.mexico_mty;
  } else if (mexicoKw.some(k => q.includes(k))) {
    detected = biasMap.mexico_cdmx;
  } else if (q.includes('peru')) {
    detected = biasMap.peru_lima;
  } else if (q.includes('mexico')) {
    detected = biasMap.mexico_cdmx;
  }
}

// Default to Peru/Lima if nothing detected (most common)
if (!detected) {
  detected = biasMap.peru_lima;
}

return [{
  json: {
    query: query.trim(),
    locationBias: detected.bias,
    detectedCountry: detected.country,
    detectedCity: detected.city,
  }
}];

const input = $input.first().json;
const candidates = input.candidates || [];
// Get country/city from Preparar Query node (not from HTTP response)
const prepData = $('Preparar Query').first().json;
const detectedCountry = prepData.detectedCountry || '';
const detectedCity = prepData.detectedCity || '';

if (!candidates.length) {
  return [{
    json: {
      latitud: '',
      longitud: '',
      format_adress: '',
      Cuidad: detectedCity,
      'País': detectedCountry,
      error: 'No geocoding results'
    }
  }];
}

const result = candidates[0];
const lat = result.geometry?.location?.lat || '';
const lng = result.geometry?.location?.lng || '';
const formattedAddress = result.formatted_address || '';

// Parse city from formatted address
// Patterns: "Street, District PostalCode, Country"
//           "Street, District, City, State, Country"
const parts = formattedAddress.split(', ');
const country = parts.length > 1 ? parts[parts.length - 1] : detectedCountry;

// Extract city/district: second-to-last part (remove postal code if present)
let ciudad = detectedCity;
if (parts.length >= 3) {
  // Get the part just before the country
  let cityPart = parts[parts.length - 2];
  // Remove postal code patterns (5 digits, or "CDMX", state abbreviations)
  cityPart = cityPart.replace(/\b\d{4,6}\b/g, '').trim();
  // For Mexico, the state abbreviation might be the last part
  if (['CDMX', 'Jal.', 'N.L.', 'Edomex'].some(s => cityPart.includes(s))) {
    // Look one level deeper
    if (parts.length >= 4) {
      cityPart = parts[parts.length - 3].replace(/\b\d{4,6}\b/g, '').trim();
    }
  }
  if (cityPart) ciudad = cityPart;
}

return [{
  json: {
    latitud: String(lat),
    longitud: String(lng),
    format_adress: formattedAddress,
    Cuidad: ciudad,
    'País': country,
  }
}];

